510	/**
511	 * Predicate that resumes a descending listing after `cursor`. Returns
512	 * `undefined` for a first page or an unparseable cursor — a bad cursor
513	 * degrades to "start from the top", never to an error page.
514	 */
515	export function keysetPredicate(
516	  sort: KeysetSort,
517	  cursor: string | null | undefined,
518	): SQL | undefined {
519	  if (!cursor) return undefined;
520	  const decoded = decodeCursor(cursor);
521	  if (!decoded) return undefined;
522	
523	  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
524	}
