531	/**
532	 * Turns an over-fetched row array into a `Page`, dropping the probe row and
533	 * deriving the next cursor from the last row that survived.
534	 */
535	export function toPage<TRow, TOut>(
536	  rows: readonly TRow[],
537	  limit: number,
538	  total: number,
539	  map: (row: TRow) => TOut,
540	  cursorOf: (row: TRow) => { id: string; sortValue: string },
541	): Page<TOut> {
542	  const capped = Math.max(1, Math.min(limit, 100));
543	  const hasMore = rows.length > capped;
544	  const visible = hasMore ? rows.slice(0, capped) : rows;
545	  const last = visible.at(-1);
546	
547	  const nextCursor =
548	    hasMore && last
549	      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
550	      : null;
551	
552	  return makePage(visible.map(map), nextCursor, total);
553	}
