  "closed",
];

/**
 * Expands a list of statuses and/or group names into plain statuses, without
 * duplicates and in order of first appearance. Unknown values are dropped.
 */
export function expandIssueStatuses(
  values: readonly string[],
): readonly IssueStatus[] {
  const expanded: IssueStatus[] = [];
  for (const value of values) {
    const members: readonly IssueStatus[] = Object.hasOwn(
      ISSUE_STATUS_GROUPS,
      value,
