export function isStatusGroupActive(
  filter: IssueFilter,
  group: IssueStatusGroup,
): boolean {
  const current = filter.status ?? [];
  return ISSUE_STATUS_GROUPS[group].every((status) => current.includes(status));
}

/** Selects every status of a group at once, or clears them when all are on. */
export function toggleStatusGroup(
  filter: IssueFilter,
  group: IssueStatusGroup,
): IssueFilter {
  const members = ISSUE_STATUS_GROUPS[group];
